-- Rewrite personal-data CMS page to short EN notice.
-- Regenerated from packages/api/src/cmsPersonalDataSeedContent.ts (en).
--
-- Locale guard (one language per D1 / deployment — see docs/i18n-prep.md):
-- Applies only when admin_settings.ui_locale = 'en'.
-- Other locales leave this page unchanged. Safe to ship all three migrations together.

UPDATE cms_pages
SET title = 'Personal data and privacy',
    description = 'A short overview of what data we store about you and why — for subscribers in the EU, mainly in Czechia and Slovakia.',
    content = '[{"type":"rich_text","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We run this service for subscribers in the EU, mainly in Czechia and Slovakia. Below is a short overview of what data we store about you and why."}]},{"type":"paragraph","content":[{"type":"text","text":"This page does not block you or force a decision — it''s informational only. Until you sign in, subscribe, or change player settings (e.g. playback speed), we don''t store anything beyond the strict technical minimum."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Signed-out visitors"}]},{"type":"paragraph","content":[{"type":"text","text":"Without signing in, you can browse public pages and video previews without us storing anything in your browser. We measure traffic anonymously via Umami (EU) — no cookies, no cross-site tracking."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When you use active features"}]},{"type":"paragraph","content":[{"type":"text","text":"Signing in, subscribing, notifications, installing the web app (PWA), or changing playback speed require storing a small amount of data in your browser. You can avoid this entirely by not using these features."}]}]}},{"type":"table","columns":["What","For","How long"],"columnKeys":["what","purpose","lifetime"],"rows":[{"what":"refresh_token","purpose":"keeps you signed in","lifetime":"up to 30 days / until logout"},{"what":"playbackRate","purpose":"remembers your playback speed","lifetime":"until you clear site data"},{"what":"nuxt-color-mode","purpose":"light/dark display mode","lifetime":"until you clear site data"},{"what":"vmp_pwa_device_token, vmp_pwa_login_email, vmp-pwa-auth","purpose":"sign-in via installed iOS app","lifetime":"until logout / cleared"},{"what":"service worker cache","purpose":"faster offline app loading","lifetime":"while the app is installed"},{"what":"session data (sessionStorage)","purpose":"security during sign-in","lifetime":"until tab is closed"},{"what":"vmp_personal_data_notice_ack","purpose":"stops this banner reappearing","lifetime":"until you clear site data"}]},{"type":"rich_text","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We don''t use any of this for advertising or profiling."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Who processes data"}]},{"type":"paragraph","content":[{"type":"text","text":"Hosting runs on Cloudflare (with Deno Deploy / Vercel as backup). Payments go through Stripe, emails through Brevo, error tracking through Sentry, traffic stats through Umami (EU). Each one only sees the data needed for its job."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Playback tracking"}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re signed in, we store where you last stopped watching a video so you can resume. You can delete this position anytime from \"Continue watching\" in your account."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Your rights"}]},{"type":"paragraph","content":[{"type":"text","text":"You have the right to access, correct, delete, restrict, or transfer your data. Just email vmp@tjm.sk — including requests to fully delete your account."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re not satisfied with how we handle your request, you can contact:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Czechia — ÚOOÚ (uoou.cz)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Slovakia — ÚOO SR (dataprotection.gov.sk)"}]}]}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We may update this page over time; the current version is always here."}]}]}}]',
    updated_at = CURRENT_TIMESTAMP
WHERE id = 'cms-page-personal-data'
  AND (
    EXISTS (
      SELECT 1 FROM admin_settings
      WHERE key = 'ui_locale' AND TRIM(value) = 'en'
    )
  );
